  "std/js/promise.d.pengu": "-- Promesas de JavaScript.\n--\n-- En PenguScript se espera con `await`: el equivalente a `then` es\n-- `const r = await promesa`. `js::Promise<T>` existe para interoperar con\n-- APIs que devuelven promesas; para escribir funciones asíncronas propias se\n-- usa `async`/`future<T>` del lenguaje.\n\nrealm js_promise\ninvoke \"std/js/types\"\n\ndeclare\n  resolve = (valor: any) -> future<any>\n  reject = (motivo: any) -> future<any>\n  all = (promesas: vector<future<any>>) -> future<vector<any>>\n  all_settled = (promesas: vector<future<any>>) -> future<vector<any>>\n  race = (promesas: vector<future<any>>) -> future<any>\n  any_of = (promesas: vector<future<any>>) -> future<any>\n",
